export const workspaceLanguages = [
  { id: "en", label: "English" },
  { id: "es", label: "Español" },
  { id: "ko", label: "한국어" },
  { id: "zh", label: "简体中文" },
  { id: "ja", label: "日本語" },
] as const;

export type WorkspaceLanguage = typeof workspaceLanguages[number]["id"];

export function isWorkspaceLanguage(value: unknown): value is WorkspaceLanguage {
  return workspaceLanguages.some(({ id }) => id === value);
}

