type WorkspaceMessage = keyof typeof messages;
const catalogIndex = { es: 0, ko: 1, zh: 2, ja: 3 } as const;

export function sentinelWorkspaceText(language: WorkspaceLanguage) {
  return (message: string, values?: Readonly<Record<string, string | number>>): string => {
    const template = language === "en" || !Object.hasOwn(messages, message)
      ? message
      : messages[message as WorkspaceMessage][catalogIndex[language]];
    return values ? template.replace(/\{(\w+)\}/g, (match, key) =>
      Object.hasOwn(values, key) ? String(values[key]) : match) : template;
  };
}
